{
  "implementation": "def solve(case):
    if not isinstance(case, dict) or 'payload' not in case:
        raise ValueError('Invalid case')
    payload = case['payload']
    text = payload.get('text')
    passes = payload.get('passes')
    max_rounds = payload.get('max_rounds')
    if not isinstance(text, str) or not isinstance(passes, list) or not isinstance(max_rounds, int):
        raise ValueError('Invalid payload types')
    for p in passes:
        if not all(k in p for k in ('name', 'old', 'new')) or not all(isinstance(p[k], str) for k in ('name', 'old', 'new')):
            raise ValueError('Invalid pass structure')
    current = text
    trace = []
    fixed_point = False
    for _ in range(max_rounds):
        changed = []
        for p in passes:
            idx = current.find(p['old'])
            if idx != -1:
                current = current[:idx] + p['new'] + current[idx + len(p['old']):]
                changed.append(p['name'])
        if changed:
            trace.append(changed)
        else:
            fixed_point = True
            break
    return {'artifact': current, 'trace': trace, 'fixed_point': fixed_point}"
}
